def test_output_token(run, x):
    assert run(x).strip() in ('YES', 'NO')


def test_single_cell(run, x):
    parts = x.split()
    n, m = map(int, parts[:2])
    out = run(x).strip()
    assert out in ('YES', 'NO')
    if n == 1 and m == 1:
        assert out == 'YES'


def test_one_row(run, x):
    from collections import Counter
    parts = x.split()
    n, m = map(int, parts[:2])
    out = run(x).strip()
    assert out in ('YES', 'NO')
    if n == 1:
        assert (out == 'YES') == (sum(v % 2 for v in Counter(parts[2]).values()) <= 1)


def test_one_column(run, x):
    from collections import Counter
    parts = x.split()
    n, m = map(int, parts[:2])
    out = run(x).strip()
    assert out in ('YES', 'NO')
    if m == 1:
        letters = [parts[2 + i] for i in range(n)]
        assert (out == 'YES') == (sum(v % 2 for v in Counter(letters).values()) <= 1)


def test_small_square(run, x):
    from itertools import permutations
    from collections import Counter
    p = x.split(); n, m = map(int, p[:2]); a = p[2:]
    out = run(x).strip(); assert out in ('YES', 'NO')
    if n <= 3 and m <= 3:
        ok = False
        for q in permutations(range(n)):
            c = Counter(''.join(a[i][j] for i in q) for j in range(m))
            if all(c[s] == c[s[::-1]] for s in c) and sum(c[s] % 2 for s in c if s == s[::-1]) == m % 2:
                ok = True; break
        assert (out == 'YES') == ok


