        for c,ch in enumerate(g[r]):
            if ch=='S': s=(r,c)
            elif ch=='T': t=(r,c)
            elif ch=='o': o.append((r,c))
    best=10**9
    for m in range(1<<len(o)):
        a=[s,t]+[v for i,v in enumerate(o) if not (m>>i)&1]
        seen={s}; q=[s]
        for u in q:
            for v in a:
                if v not in seen and (u[0]==v[0] or u[1]==v[1]): seen.add(v); q.append(v)
        if t not in seen: best=min(best,m.bit_count())
    assert run(x).strip()==str(-1 if best==10**9 else best)

