def test_output_range(run, x):
    n = int(x.split()[0])
    answer = int(run(x).strip())
    assert 0 <= answer <= n


def test_zero_feasibility(run, x):
    z = list(map(int, x.split()))
    n, I, a = z[0], z[1], z[2:]
    k = (len(set(a)) - 1).bit_length()
    answer = int(run(x).strip())
