def test_perm_123(run, x):
    p = list(map(int, x.split()))
    n, T = p[:2]
    a = p[2:] * T
    d = [1] * len(a)
    for i in range(len(a)):
        for j in range(i):
            if a[j] <= a[i] and d[j] + 1 > d[i]:
                d[i] = d[j] + 1
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == max(d)

