def test_single_period(run, x):
    p = x.split()
    n, T = map(int, p[:2])
    a = list(map(int, p[2:]))
    got = int(run(x).strip())
    if n == 1:
        assert got == T
        return
    if n * T <= 1000:
        z = a * T
        d = []
        for i, v in enumerate(z):
            best = 1
            for j in range(i):
                if z[j] <= v and d[j] + 1 > best:
                    best = d[j] + 1
            d.append(best)
        assert got == max(d)


