                piece = s[pos:pos+width]
                if piece != last:
                    visit(pos + width, piece, pieces + [piece])
    for pos in range(5, n + 1):
        visit(pos, None, [])
    output = run(x).split()
    assert output == [str(len(expected))] + sorted(expected)"},{"name":"test_mixed_tail","source":"def test_mixed_tail(run, x):
    s = x.strip()
    n = len(s)
