    tokens = run(x).split()
    assert tokens == [str(len(possible))] + sorted(possible)"},{"name":"test_distinct_blocks","source":"def test_distinct_blocks(run, x):
    s = x.strip()
    n = len(s)
    valid = set()
    def walk(i, previous, blocks):
        if i == n:
