    n, k = map(int, x.split())
    got = int(run(x).strip())
    if n > 5:
        return
    deques = {(1,)}
    for card in range(2, n + 1):
        deques = {(card,) + d for d in deques} | {d + (card,) for d in deques}
    orders = set()
    def eat(d, p):
        if not d:
            orders.add(p)
        else:
            eat(d[1:], p + (d[0],))
            eat(d[:-1], p + (d[-1],))
    for d in deques:
        eat(d, ())
    assert got == sum(order[k - 1] == 1 for order in orders)


