def test_component_completion_oracle(run, x):
    z = list(map(int, x.split()))
    n, m, k = z[:3]
    gov = set(v - 1 for v in z[3:3 + k])
    g = [[] for _ in range(n)]
    p = 3 + k
    for i in range(m):
        a, b = z[p + 2*i] - 1, z[p + 2*i + 1] - 1
        g[a].append(b); g[b].append(a)
    seen = [False] * n
    sizes, free = [], 0
    for start in range(n):
        if seen[start]:
            continue
        stack = [start]; seen[start] = True; comp = []
        while stack:
            v = stack.pop(); comp.append(v)
            for w in g[v]:
                if not seen[w]: seen[w] = True; stack.append(w)
        if any(v in gov for v in comp): sizes.append(len(comp))
        else: free += len(comp)
    biggest = max(sizes)
    total = sum(s * (s - 1) // 2 for s in sizes) - biggest * (biggest - 1) // 2
    total += (biggest + free) * (biggest + free - 1) // 2
    assert int(run(x).strip()) == total - m

def test_exhaustive_small_oracle(run, x):
    z = list(map(int, x.split())); n, m, k = z[:3]
    ans = int(run(x).strip())
    if n > 6:
        assert ans >= 0
        return
    gov = [v - 1 for v in z[3:3+k]]
    edges = set(); p = 3 + k
    for i in range(m):
        a, b = z[p+2*i]-1, z[p+2*i+1]-1
        edges.add((min(a,b), max(a,b)))
    missing = [(a,b) for a in range(n) for b in range(a+1,n) if (a,b) not in edges]
    best = 0
    for mask in range(1 << len(missing)):
        par = list(range(n))
        def find(a):
            while par[a] != a:
                par[a] = par[par[a]]; a = par[a]
            return a
        for a,b in list(edges) + [missing[i] for i in range(len(missing)) if mask >> i & 1]:
            a,b=find(a),find(b)
            if a != b: par[a]=b
        if len({find(v) for v in gov}) == k: best=max(best, mask.bit_count())
    assert ans == best

