def test_exact_oracle(run, x):
    rows = [list(map(int, z.split())) for z in x.strip().splitlines()]
    n, a = rows[0][0], rows[1:]
    s = run(x).strip()
    assert s.isdigit()
    got = int(s)
    ori = [[tuple(r[k:] + r[:k]) for k in range(4)] for r in a]
    total = 0
    for u in range(n):
        for du in range(4):
            A, B, C, D = ori[u][du]
            for v in range(n):
                if v == u:
                    continue
                for dv in range(4):
                    E, H, G, F = ori[v][dv]
                    need = [(A,E,F,B), (B,F,G,C), (C,G,H,D), (D,H,E,A)]
                    def fill(p, used):
                        if p == 4:
                            return 1
                        z = 0
                        for t in range(n):
                            if t not in used:
                                for q in ori[t]:
                                    if q == need[p]:
                                        z += fill(p + 1, used | {t})
                        return z
                    total += fill(0, {u, v})
    assert got == total // 24

