def test_exhaustive_known_ratios(run, x):
    import math
    if not hasattr(test_exhaustive_known_ratios, 'answers'):
        L = 12000000
        prime = bytearray(b'\x01') * (L + 1)
        prime[0:2] = b'\x00\x00'
        for d in range(2, math.isqrt(L) + 1):
            if prime[d]:
                start = d * d
                prime[start:L + 1:d] = b'\x00' * (((L - start) // d) + 1)
        pal = bytearray(L + 1)
        for h in range(1, 10000):
            s = str(h)
            a = int(s + s[-2::-1])
            b = int(s + s[::-1])
            if a <= L: pal[a] = 1
            if b <= L: pal[b] = 1
        ratios = [(1,42),(238,9996),(1,3),(1,2),(2,3),(3,2),(5,2),(10000,10000),(10000,239),(9996,238)]
        ans = {r: 0 for r in ratios}
        pc = rc = 0
        for n in range(1, L + 1):
            pc += prime[n]
            rc += pal[n]
            for p, q in ratios:
                if q * pc <= p * rc:
                    ans[(p, q)] = n
        test_exhaustive_known_ratios.answers = ans
    p, q = map(int, x.split())
    assert int(run(x).strip()) == test_exhaustive_known_ratios.answers[(p, q)]

